.study-layout { display: grid; grid-template-columns: 1fr; gap: 1.5rem; }
.study-article { min-width: 0; max-width: 72ch; margin: auto; }
.lesson-table { max-width: 100%; overflow-x: auto; }
.study-card { transition: transform .2s ease, border-color .2s ease; }
.study-card:hover { transform: translateY(-2px); }
@media (min-width: 1024px) {
  .study-layout { grid-template-columns: 250px minmax(0, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
  .study-card { transition: none; }
  .study-card:hover { transform: none; }
}

const input = document.querySelector('#lesson-search');
const list = document.querySelector('#lesson-list');
const count = document.querySelector('#results-count');

input.addEventListener('input', () => {
  const term = input.value.trim().toLowerCase();
  let visible = 0;
  for (const lesson of list.querySelectorAll('[data-lesson-title]')) {
    const matches = lesson.dataset.lessonTitle.toLowerCase().includes(term);
    lesson.hidden = !matches;
    if (matches) visible++;
  }
  count.textContent = visible + ' lessons found';
});
